import { View, Text, FlatList, StyleSheet } from "react-native";
import { registerRootComponent } from "expo";

const PRODUCTS = [
  { id: "1", name: "Чихэвч", price: "159,000₮" },
  { id: "2", name: "Гар цаг", price: "249,000₮" },
  { id: "3", name: "Нарны шил", price: "89,000₮" },
  { id: "4", name: "Цүнх", price: "129,000₮" },
];

function App() {
  return (
    <View style={styles.screen}>
      <FlatList
        data={PRODUCTS}
        keyExtractor={(item) => item.id}
        renderItem={({ item }) => (
          <View testID="row" style={styles.row}>
            <Text style={styles.name}>{item.name}</Text>
            <Text style={styles.price}>{item.price}</Text>
          </View>
        )}
      />
    </View>
  );
}

const styles = StyleSheet.create({
  screen: { flex: 1, backgroundColor: "#f5f6f8" },
  row: { backgroundColor: "#ffffff", padding: 16, margin: 8, borderRadius: 12, flexDirection: "row", justifyContent: "space-between" },
  name: { fontSize: 16, fontWeight: "600" },
  price: { fontSize: 16, fontWeight: "bold", color: "#2563eb" },
});

registerRootComponent(App);
